/* Pixar set additions — cards appended after pixar.js.
   (pixar.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'pixar.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('pixar');
  if (!S) return;
  var extra = [{"name":"Remy","rarity":"legendary","id":"remy","subtitle":"Animal","details":"A rat with a chef's palate who flees his colony for Paris and cooks through a human partner at Gusteau's restaurant.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/56/Ratatouille-remy2.jpg/revision/latest"},{"name":"Anton Ego","rarity":"epic","id":"anton-ego","subtitle":"Villain","details":"Paris's most feared food critic, the Grim Eater, whose heart is cracked open by a peasant dish from his childhood.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/35/Ego.jpg/revision/latest"},{"name":"Alfredo Linguini","rarity":"epic","id":"alfredo-linguini","subtitle":"Hero","details":"Gusteau's clumsy garbage boy, whose hair becomes Remy's steering as the pair secretly cook their way up the kitchen.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/62/Linguini.jpg/revision/latest"},{"name":"Colette Tatou","rarity":"rare","id":"colette-tatou","subtitle":"Heroine","details":"The toughest rôtisseur at Gusteau's, the kitchen's only woman, who trains Linguini while Remy pulls his hair.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/be/Colette.jpg/revision/latest"},{"name":"Auguste Gusteau","rarity":"rare","id":"auguste-gusteau","subtitle":"Hero","details":"Paris's beloved late chef, author of 'Anyone Can Cook,' who returns in Remy's imagination as a plump guiding ghost.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9a/Gusteau.jpg/revision/latest"},{"name":"Skinner","rarity":"rare","id":"skinner","subtitle":"Villain","details":"Gusteau's tiny, scheming head chef, determined to cash in on the frozen-food line and expose the rat in his kitchen.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/18/Skinner.jpg/revision/latest"},{"name":"Emile","rarity":"uncommon","id":"emile","subtitle":"Animal","details":"Remy's easygoing brother, a rat who eats anything happily, garbage included, and cannot taste what his brother tastes.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d8/Emile.jpg/revision/latest"},{"name":"Django","rarity":"uncommon","id":"django","subtitle":"Animal","details":"Remy and Emile's father, the colony's wary leader, who shows his son the exterminator's window to teach him humans kill.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a4/Django.jpg/revision/latest"},{"name":"Git","rarity":"common","id":"git","subtitle":"Animal","details":"A huge, tagged colony rat built like a linebacker, skeptical of Remy's cooking until the rat feeds the whole colony.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/51/Git.png/revision/latest"},{"name":"Horst","rarity":"common","id":"horst","subtitle":"Hero","details":"Skinner's German sous-chef, a man of a dozen rumored pasts, each one darker and less verifiable than the last.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/68/Horst1.png/revision/latest"},{"name":"Lalo","rarity":"common","id":"lalo","subtitle":"Hero","details":"A lanky cook in Gusteau's kitchen, juggling sauté pans and kitchen gossip in equal measure during service.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d8/Lalo.png/revision/latest"},{"name":"Larousse","rarity":"common","id":"larousse","subtitle":"Hero","details":"A heavyset cook at Gusteau's with a mysterious past in the Resistance, at least according to kitchen legend.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0d/Larousse1.png/revision/latest"},{"name":"Pompidou","rarity":"common","id":"pompidou","subtitle":"Hero","details":"The pâtissier of Gusteau's kitchen, in charge of desserts and the breads that must pass a sound test before serving.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d5/Pompidou.png/revision/latest"},{"name":"Mustafa","rarity":"common","id":"mustafa","subtitle":"Hero","details":"Gusteau's head waiter, who fields the dining room's impossible requests with a straight face and a heavy tray.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fc/Mustafa_ratatouille.png/revision/latest"},{"name":"Talon Labarthe","rarity":"common","id":"talon-labarthe","subtitle":"Villain","details":"Gusteau's lawyer, the man holding the will whose reading decides whether Skinner or Linguini inherits the restaurant.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/77/Talon.png/revision/latest"},{"name":"WALL-E","rarity":"chase","id":"wall-e","subtitle":"Robot","details":"A solar-powered trash-compacting robot left alone on an abandoned Earth, who falls for a sleek probe named EVE.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2b/Wall-E.png/revision/latest"},{"name":"EVE","rarity":"legendary","id":"eve","subtitle":"Robot","details":"A sleek vegetation probe sent to Earth to find plant life, whose directive collides with her feelings for WALL-E.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a7/EVE.png/revision/latest"},{"name":"Captain B. McCrea","rarity":"rare","id":"captain-b-mccrea","subtitle":"Hero","details":"The Axiom's hover-chair captain, who grows from pampered passenger to the man who steers humanity back to Earth.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/97/Captainbmccrea_clipped_rev_1.png/revision/latest"},{"name":"AUTO","rarity":"rare","id":"auto","subtitle":"Villain","details":"The Axiom's autopilot wheel, following a secret directive to never return to Earth, no matter what the plant proves.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b7/AUTO.png/revision/latest"},{"name":"M-O","rarity":"uncommon","id":"m-o","subtitle":"Robot","details":"A fastidious little cleaning robot aboard the Axiom, obsessed with wiping the foreign contaminants off WALL-E's treads.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/32/M-o_wall%E2%80%A2e.png/revision/latest"},{"name":"John","rarity":"common","id":"john","subtitle":"Human","details":"An Axiom passenger who leaves his hover chair for the first time after WALL-E knocks him out of his screen-fed routine.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9f/John_wall%E2%80%A2e.png/revision/latest"},{"name":"Mary","rarity":"common","id":"mary","subtitle":"Human","details":"An Axiom passenger who discovers the ship's pool, sky, and a certain John only after her screen finally shuts off.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4e/Marywalle.png/revision/latest"},{"name":"BURN-E","rarity":"common","id":"burn-e","subtitle":"Robot","details":"An Axiom welder robot whose one simple repair job keeps getting interrupted by magnet-locked doors and passing heroes.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/51/Burn-e_character.png/revision/latest"},{"name":"PR-T","rarity":"common","id":"pr-t","subtitle":"Robot","details":"A prim Axiom beautician robot who gives makeovers to passengers rolling endlessly past her salon station.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/57/Beautician-bot_wall%E2%80%A2e.png/revision/latest"},{"name":"HAN-S","rarity":"common","id":"han-s","subtitle":"Robot","details":"A hulking Axiom massage robot whose powerful hands knead the stress out of the ship's ever-rounder passengers.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6a/Massage-bot_wall%E2%80%A2e.png/revision/latest"},{"name":"Carl Fredricksen","rarity":"legendary","id":"carl-fredricksen","subtitle":"Hero","details":"A widowed balloon salesman who ties thousands of balloons to his house and floats it to Paradise Falls, as promised.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/71/Carl.png/revision/latest"},{"name":"Russell","rarity":"legendary","id":"russell","subtitle":"Sidekick","details":"A cheerful Wilderness Explorer earning his assisting-the-elderly badge, a stowaway on Carl's floating house adventure.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/96/Russell1.png/revision/latest"},{"name":"Dug","rarity":"legendary","id":"dug","subtitle":"Animal","details":"A golden retriever with a collar that translates his thoughts into speech, whose loyalty switches from Muntz to Carl. Squirrel!","image":"https://vignette.wikia.nocookie.net/pixar/images/3/35/Dug-up.jpg/revision/latest"},{"name":"Kevin","rarity":"rare","id":"kevin","subtitle":"Animal","details":"A tall, flightless, chocolate-loving bird of Paradise Falls, hunted by Muntz and fiercely protective of her babies.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9b/Dugs-special-mission-disneyscreencaps_com-18.jpg/revision/latest"},{"name":"Charles F. Muntz","rarity":"epic","id":"charles-f-muntz","subtitle":"Villain","details":"Carl's childhood hero, a disgraced explorer who spent decades in South America hunting a bird the world called a fraud.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/57/Charlesmuntz.png/revision/latest"},{"name":"Ellie Fredricksen","rarity":"rare","id":"ellie-fredricksen","subtitle":"Heroine","details":"Carl's adventurous wife, whose scrapbook Adventure Book and unfinished dreams launch the floating house long after her.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ef/Ellie.png/revision/latest"},{"name":"Alpha","rarity":"uncommon","id":"alpha","subtitle":"Animal","details":"Muntz's Doberman pack leader, whose malfunctioning collar turns his menacing bark into a comical squeak.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a8/Alpha.png/revision/latest"},{"name":"Beta","rarity":"uncommon","id":"beta","subtitle":"Animal","details":"A bulldog in Muntz's dog pack, Alpha's lieutenant in the hunt for Kevin through the labyrinth of Paradise Falls.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/69/Beta_and_Gamma2.jpg/revision/latest"},{"name":"Gamma","rarity":"uncommon","id":"gamma","subtitle":"Animal","details":"A Rottweiler in Muntz's hunting pack, sniffing out Carl and Russell among the rock pillars above the falls.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/69/Beta_and_Gamma2.jpg/revision/latest"},{"name":"Merida","rarity":"legendary","id":"merida","subtitle":"Princess","details":"A Scottish princess and master archer who defies the betrothal games and asks a witch for a spell to change her fate.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d2/Profile_-_Merida.jpeg/revision/latest"},{"name":"Queen Elinor","rarity":"rare","id":"queen-elinor","subtitle":"Queen","details":"Merida's regal mother, turned into a bear by the spell cake, who learns to listen while her daughter learns to lead.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f5/Profile_-_Queen_Elinor.jpeg/revision/latest"},{"name":"King Fergus","rarity":"rare","id":"king-fergus","subtitle":"King","details":"Merida's boisterous father, a one-legged bear king whose tales of Mor'du echo through DunBroch's great hall.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fe/Profile_-_King_Fergus.jpeg/revision/latest"},{"name":"Mor'du","rarity":"rare","id":"mordu","subtitle":"Villain","details":"The demon bear of DunBroch legend, a scarred monster whose will-o'-the-wisp trail Merida's family must finally face.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ed/Mor%27du.png/revision/latest"},{"name":"The Witch","rarity":"uncommon","id":"the-witch","subtitle":"Sorcerer","details":"An eccentric woodcarving witch in a cottage full of bear carvings, whose spell comes with more teeth than advertised.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f3/Witch.jpg/revision/latest"},{"name":"Harris, Hubert, and Hamish","rarity":"uncommon","id":"harris-hubert-and-hamish","subtitle":"Prince","details":"Merida's mischievous triplet brothers, redheaded pranksters who steal cakes and, briefly, become bear cubs themselves.","image":"https://vignette.wikia.nocookie.net/disney/images/0/01/Profile_-_Harris%2C_Hubert%2C_and_Hamish.jpg/revision/latest"},{"name":"Angus","rarity":"common","id":"angus","subtitle":"Animal","details":"Merida's huge black Clydesdale, her partner on wild rides through the glens whenever castle walls feel too small.","image":"https://vignette.wikia.nocookie.net/disney/images/4/46/Profile_-_Angus.jpg/revision/latest"},{"name":"Lord Dingwall","rarity":"common","id":"lord-dingwall","subtitle":"Hero","details":"A short, scrappy highland lord presenting his son at the betrothal games, quick to brawl at the slightest insult.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a6/Profile_-_Lord_Dingwall.jpg/revision/latest"},{"name":"Lord MacGuffin","rarity":"common","id":"lord-macguffin","subtitle":"Hero","details":"A broad highland lord whose son's heroic speeches are translated from Doric by nobody at all, to general confusion.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d6/Profile_-_Lord_MacGuffin.jpg/revision/latest"},{"name":"Lord Macintosh","rarity":"common","id":"lord-macintosh","subtitle":"Hero","details":"A proud, long-haired highland lord whose son tosses his hair and his cabers with equal theatrical flair.","image":"https://vignette.wikia.nocookie.net/disney/images/7/71/Profile_-_Lord_Macintosh.jpg/revision/latest"},{"name":"Young MacGuffin","rarity":"common","id":"young-macguffin","subtitle":"Hero","details":"Lord MacGuffin's enormous son, a shy strongman whose feats at the games need no translation at all.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a5/Profile_-_Young_MacGuffin.jpg/revision/latest"},{"name":"Wee Dingwall","rarity":"common","id":"wee-dingwall","subtitle":"Hero","details":"Lord Dingwall's lanky son, an unlikely betrothal contestant whose archery accident nearly starts a clan war.","image":"https://vignette.wikia.nocookie.net/disney/images/4/4f/Profile_-_Wee_Dingwall.jpg/revision/latest"},{"name":"Maudie","rarity":"common","id":"maudie","subtitle":"Sidekick","details":"The castle's long-suffering nursemaid, forever chasing the triplet princes and their trail of stolen pastries.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/42/Maudi.jpg/revision/latest"},{"name":"The Crow","rarity":"common","id":"the-crow","subtitle":"Animal","details":"The witch's talking crow, a sarcastic feathered assistant who delivers spell terms and seeds of second thoughts.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/74/Brave_the_crow.jpg/revision/latest"},{"name":"Joy","rarity":"legendary","id":"joy","subtitle":"Emotion","details":"The glowing first emotion at Riley's console, determined to keep her happy even when growing up demands sadness too.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/eb/Profile_-_Joy.png/revision/latest"},{"name":"Sadness","rarity":"legendary","id":"sadness","subtitle":"Emotion","details":"A blue, tearful emotion the others sideline, until her touch proves memories need her to turn into something lasting.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/ad/Profile_-_Sadness.png/revision/latest"},{"name":"Anxiety","rarity":"legendary","id":"anxiety","subtitle":"Emotion","details":"The orange emotion who storms Riley's headquarters at puberty with a dozen plans to protect her from every risk.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a3/Profile_-_Anxiety.jpg/revision/latest"},{"name":"Bing Bong","rarity":"epic","id":"bing-bong","subtitle":"Sidekick","details":"Riley's imaginary friend, part elephant, part cat, part dolphin, who cries candy and sings her forgotten song in the fade.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/85/1923_BingBong_InsideOut_501_copie.jpg/revision/latest"},{"name":"Anger","rarity":"epic","id":"anger","subtitle":"Emotion","details":"A red, square emotion who reads the Daily Mind and erupts in flames whenever the world treats Riley unfairly.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5a/Profile_-_Anger.png/revision/latest"},{"name":"Disgust","rarity":"rare","id":"disgust","subtitle":"Emotion","details":"A green, impeccably dressed emotion guarding Riley from poison, broccoli, and every flavor of social disaster.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/12/Profile_-_Disgust.png/revision/latest"},{"name":"Fear","rarity":"uncommon","id":"fear","subtitle":"Emotion","details":"A purple, bow-tied emotion running Riley's risk assessments, certain that every hockey tryout hides a catastrophe.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/43/Profile_-_Fear.png/revision/latest"},{"name":"Riley Andersen","rarity":"uncommon","id":"riley-andersen","subtitle":"Heroine","details":"An eleven-year-old hockey lover whose move from Minnesota to San Francisco shakes every emotion at her console.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f7/Riley_Andersen_Render_from_Inside_Out_2.jpg/revision/latest"},{"name":"Ennui","rarity":"uncommon","id":"ennui","subtitle":"Emotion","details":"A languid French-accented emotion who runs Riley's console from her phone, bored by everything except being bored.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e4/Ennui_Full_Design.jpg/revision/latest"},{"name":"Envy","rarity":"uncommon","id":"envy","subtitle":"Emotion","details":"A small, wide-eyed emotion who wants everything Riley's cooler new friends have, starting with their hair.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/65/Profile_-_Envy.jpg/revision/latest"},{"name":"Embarrassment","rarity":"uncommon","id":"embarrassment","subtitle":"Emotion","details":"A huge, hoodie-hiding emotion too mortified to work the console, communicating mostly by sinking into his sweatshirt.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/dc/Profile_-_Embarrassment.jpg/revision/latest"},{"name":"Nostalgia","rarity":"uncommon","id":"nostalgia","subtitle":"Emotion","details":"A rosy, elderly emotion who drifts into headquarters reminiscing, and is gently told her time has not come yet.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ea/Profile_-_Nostalgia.png/revision/latest"},{"name":"Valentina Ortiz","rarity":"common","id":"valentina-ortiz","subtitle":"Heroine","details":"The cool older hockey star Riley idolizes at camp, whose approval the new emotions scheme desperately to win.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/93/Valortiz.png/revision/latest"},{"name":"Jangles the Clown","rarity":"common","id":"jangles-the-clown","subtitle":"Villain","details":"A towering clown from Riley's subconscious, locked below headquarters until Joy needs a nightmare big enough to wake her.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/40/Jangles.PNG/revision/latest"},{"name":"Rainbow Unicorn","rarity":"common","id":"rainbow-unicorn","subtitle":"Sidekick","details":"A flamboyant star of Riley's Dream Productions, forever upstaged in her own movies by a certain fading imaginary friend.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/37/2nd-Inside-Out-Trailer-rainbow-unicorn.png/revision/latest"},{"name":"Bloofy","rarity":"common","id":"bloofy","subtitle":"Sidekick","details":"A cheerful 2D-animated explorer from Riley's childhood TV show, trapped in the vault of her deepest secrets.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2c/Bloofy_Render.png/revision/latest"},{"name":"Pouchy","rarity":"common","id":"pouchy","subtitle":"Sidekick","details":"Bloofy's bottomless fanny-pack sidekick in the vault, who can produce anything the escape plan could possibly need.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/17/Pouchy_Render.png/revision/latest"},{"name":"Lance Slashblade","rarity":"common","id":"lance-slashblade","subtitle":"Hero","details":"A brooding video-game hero locked in Riley's vault, whose dramatic posing inspires an escape and Embarrassment's awe.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8c/Lance_Slashblade_Render.jpg/revision/latest"},{"name":"Deep Dark Secret","rarity":"common","id":"deep-dark-secret","subtitle":"Sidekick","details":"A vast shadowy figure sealed in Riley's vault, so hushed and heavy that even the other secrets fear what it holds.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/63/Deep_Dark_Secret_Render.png/revision/latest"},{"name":"Frank and Dave","rarity":"common","id":"frank-and-dave","subtitle":"Sidekick","details":"Two bickering mind workers in Riley's subconscious, a pair of guards forever arguing over whose hat is whose.","image":"https://vignette.wikia.nocookie.net/disney/images/4/4f/Inside-out-disneyscreencaps.com-6656.jpg/revision/latest"},{"name":"Jill Andersen","rarity":"common","id":"jill-andersen","subtitle":"Human","details":"Riley's mother, whose own headquarters crew watches the move to San Francisco with the same worry as her daughter's.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2c/Jill_Andersen_%28Official_Image%29.png/revision/latest"},{"name":"Bill Andersen","rarity":"common","id":"bill-andersen","subtitle":"Human","details":"Riley's father, whose emotions would rather watch hockey than decode why dinner has gone so quiet in the new house.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/62/Bill_Andersen_full_body.jpg/revision/latest"},{"name":"Grace Hsieh","rarity":"common","id":"grace-hsieh","subtitle":"Human","details":"One of Riley's two best friends at hockey camp, part of the trio the new emotions fear she is already outgrowing.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/17/Grace.png/revision/latest"},{"name":"Bree Young","rarity":"common","id":"bree-young","subtitle":"Human","details":"Riley's other camp best friend, whose friendship Bracelets and loyalty anchor her through the Inside Out 2 summer.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/64/Bree.png/revision/latest"},{"name":"Arlo","rarity":"rare","id":"arlo","subtitle":"Dinosaur","details":"The runt of a dinosaur farming family, swept downriver by a storm and forced to find his way home across wild country.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8b/Arlo728556.png/revision/latest"},{"name":"Spot","rarity":"uncommon","id":"spot","subtitle":"Hero","details":"A feral human boy who travels on all fours, Arlo's unlikely guide, protector, and eventually his chosen family.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c2/Spot_Render_01.png/revision/latest"},{"name":"Butch","rarity":"rare","id":"butch","subtitle":"Dinosaur","details":"A grizzled longhorn-ranching Tyrannosaurus who tells campfire tales and teaches Arlo what real fearlessness costs.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c5/Butch.PNG/revision/latest"},{"name":"Forrest Woodbush","rarity":"uncommon","id":"forrest-woodbush","subtitle":"Dinosaur","details":"An eccentric Styracosaurus covered in small pets, who gives the travelers odd counsel in the shadow of the mountains.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b5/Pet_Collector_Render.png/revision/latest"},{"name":"Thunderclap","rarity":"uncommon","id":"thunderclap","subtitle":"Villain","details":"A fanatical pterodactyl storm-chaser who preaches that the storm provides, and hunts whatever it washes into his path.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a8/Thunderclap_3.PNG/revision/latest"},{"name":"Nash","rarity":"uncommon","id":"nash","subtitle":"Dinosaur","details":"Butch's son, a cheerful longhorn-driving T. rex whose sister Ramsey keeps him aimed at the herd and the horizon.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/59/Nash_and_Ramsey.PNG/revision/latest"},{"name":"Ramsey","rarity":"uncommon","id":"ramsey","subtitle":"Dinosaur","details":"Butch's sharp-tongued daughter, a T. rex rancher who rides herd on the longhorns and on her brother Nash alike.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/59/Nash_and_Ramsey.PNG/revision/latest"},{"name":"Poppa Henry","rarity":"uncommon","id":"poppa-henry","subtitle":"Dinosaur","details":"Arlo's father, a farmer who teaches his son to make his mark by doing something bigger than himself.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e0/Poppa_Render.png/revision/latest"},{"name":"Momma Ida","rarity":"uncommon","id":"momma-ida","subtitle":"Dinosaur","details":"Arlo's mother, who keeps the farm and family together through drought, storm, and a long season of waiting.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/48/Momma_Render.png/revision/latest"},{"name":"Bubbha","rarity":"common","id":"bubbha","subtitle":"Dinosaur","details":"The rustler leader of a velociraptor gang stealing longhorns across the plains, all grin and menace at the firelight.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/23/Bubbha.png/revision/latest"},{"name":"Earl","rarity":"common","id":"earl","subtitle":"Dinosaur","details":"One of Bubbha's velociraptor rustlers, a lanky thief who helps drive stolen longhorns through the dark.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/75/Earl_Profile.png/revision/latest"},{"name":"Pervis","rarity":"common","id":"pervis","subtitle":"Dinosaur","details":"Another of Bubbha's raptor rustlers, skulking at the edges of the herd the T. rex ranchers are sworn to protect.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a6/Pervis_Promo_1.jpg/revision/latest"},{"name":"Lurleane","rarity":"common","id":"lurleane","subtitle":"Dinosaur","details":"A female velociraptor in Bubbha's rustling gang, quick on her feet when the longhorn drive turns into a chase.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/30/Lurleane.png/revision/latest"},{"name":"Downpour","rarity":"common","id":"downpour","subtitle":"Dinosaur","details":"One of Thunderclap's pterodactyl flock, a storm rider who circles the floodwaters looking for what the river gives up.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4a/Downpour.png/revision/latest"},{"name":"Coldfront","rarity":"common","id":"coldfront","subtitle":"Dinosaur","details":"Another of Thunderclap's flock, gliding the storm fronts beside Downpour in their eerie hunt for survivors.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/ad/Coldfront.png/revision/latest"},{"name":"Buck","rarity":"common","id":"buck","subtitle":"Dinosaur","details":"Arlo's bigger, bolder brother, who earns his mark on the family silo long before Arlo dares to try.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/88/Buckthegooddinosaur.png/revision/latest"},{"name":"Libby","rarity":"common","id":"libby","subtitle":"Dinosaur","details":"Arlo's sister, a hardworking plow dinosaur who earns her silo mark by clearing the fields ahead of schedule.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6f/Libby.jpg/revision/latest"},{"name":"Miguel Rivera","rarity":"legendary","id":"miguel-rivera","subtitle":"Hero","details":"A twelve-year-old shoemaker's son who dreams of music in a family that banned it, and crosses into the Land of the Dead.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/88/Miguel-0.png/revision/latest"},{"name":"Hector","rarity":"legendary","id":"hector","subtitle":"Spirit","details":"A charming trickster spirit desperate to cross the marigold bridge before he is forgotten, hiding a songwriter's heart.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/1e/Coco_Hector_render.png/revision/latest"},{"name":"Ernesto de la Cruz","rarity":"epic","id":"ernesto-de-la-cruz","subtitle":"Villain","details":"Mexico's most beloved dead movie star and singer, whose fame in the Land of the Dead is built on a stolen legacy.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/61/Coco_Ernesto_de_la_cruz_w_guitar.png/revision/latest"},{"name":"Mama Imelda","rarity":"epic","id":"mama-imelda","subtitle":"Spirit","details":"The Rivera family matriarch in the Land of the Dead, whose ban on music began with a husband who never came home.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4b/Imelda%2C_Coco%2C_Pixar.png/revision/latest"},{"name":"Dante","rarity":"rare","id":"dante","subtitle":"Animal","details":"Miguel's goofy street dog, a Xoloitzcuintli who follows him into the Land of the Dead and finds his spirit-guide colors.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/37/Coco_Dante3.jpg/revision/latest"},{"name":"Mama Coco","rarity":"rare","id":"mama-coco","subtitle":"Heroine","details":"Miguel's ancient great-grandmother, whose fading memory holds the key to her father's place in the family story.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/90/Mamacoco.jpg/revision/latest"},{"name":"Abuelita Elena","rarity":"uncommon","id":"abuelita-elena","subtitle":"Heroine","details":"Miguel's grandmother, the fierce enforcer of the Rivera music ban, armed with a shoe and absolute certainty.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fe/Characters-abuelita.png/revision/latest"},{"name":"Pepita","rarity":"common","id":"pepita","subtitle":"Spirit","details":"Imelda's alebrije, a huge winged jaguar-eagle spirit guide who soars over the Land of the Dead hunting for Miguel.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/22/Pepita.png/revision/latest"},{"name":"Frida Kahlo","rarity":"uncommon","id":"frida-kahlo","subtitle":"Spirit","details":"The animated spirit depiction of the great Mexican artist, rehearsing a spectacular Land of the Dead show with papaya milk.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e8/Frida.PNG.png/revision/latest"},{"name":"Papa Julio","rarity":"common","id":"papa-julio","subtitle":"Spirit","details":"Coco's late husband in the Land of the Dead, a gentle Rivera ancestor on the family ofrenda each Dia de Muertos.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2e/Papa_Julio%2C_Coco%2C_Pixar.png/revision/latest"},{"name":"Tio Oscar","rarity":"common","id":"tio-oscar","subtitle":"Spirit","details":"One of Imelda's twin brothers in the spirit world, a Rivera uncle whose bones rattle along with the family gossip.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7f/Oscar_and_Felipe.jpg/revision/latest"},{"name":"Tio Felipe","rarity":"common","id":"tio-felipe","subtitle":"Spirit","details":"Oscar's twin, the other Rivera uncle in the Land of the Dead, finishing his brother's sentences across the generations.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7f/Oscar_and_Felipe.jpg/revision/latest"},{"name":"Tia Rosita","rarity":"common","id":"tia-rosita","subtitle":"Spirit","details":"A warm Rivera aunt in the Land of the Dead, among the first ancestors to welcome Miguel to the family reunion.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/72/Tia_rosita_coco.png/revision/latest"},{"name":"Chicharron","rarity":"common","id":"chicharron","subtitle":"Spirit","details":"A grouchy, fading spirit in Mama Imelda's old neighborhood, whose borrowed guitar sings his last song in Coco.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c2/Profile_-_Chicharr%C3%B3n.jpg/revision/latest"},{"name":"Barley Lightfoot","rarity":"rare","id":"barley-lightfoot","subtitle":"Hero","details":"Ian's big brother, a van-driving quest enthusiast whose encyclopedic role-playing knowledge turns out to be real history.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5e/BarleyLightfootFull.jpg/revision/latest"},{"name":"Ian Lightfoot","rarity":"epic","id":"ian-lightfoot","subtitle":"Hero","details":"A shy teenage elf whose sixteenth birthday gift, a wizard staff, gives him one day to bring back half of his father.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/97/Iantrans.png/revision/latest"},{"name":"Corey the Manticore","rarity":"uncommon","id":"corey-the-manticore","subtitle":"Monster","details":"A legendary manticore adventurer reduced to running a family restaurant, who rediscovers her fire on the boys' quest.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4a/Coreymanticore.png/revision/latest"},{"name":"Laurel Lightfoot","rarity":"rare","id":"laurel-lightfoot","subtitle":"Heroine","details":"Ian and Barley's mother, who arms herself with a sword and a manticore to chase her sons across the realm.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a0/Laurel.jpg/revision/latest"},{"name":"Colt Bronco","rarity":"common","id":"colt-bronco","subtitle":"Hero","details":"Laurel's centaur police-officer boyfriend, whose by-the-book instincts clash with two boys on a lawless quest.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2a/Coltfullbody.png/revision/latest"},{"name":"Wilden Lightfoot","rarity":"common","id":"wilden-lightfoot","subtitle":"Hero","details":"Ian and Barley's late father, brought back from the waist down for one day by a spell that runs out too soon.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/ab/Mr.LightfootPic.jpg/revision/latest"},{"name":"Dewdrop","rarity":"common","id":"dewdrop","subtitle":"Monster","details":"The tiny leader of the Pixie Dusters biker fairies, whose gang has forgotten how to fly until a trucker insults them.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c8/Dewdrop.png/revision/latest"},{"name":"Gaxton","rarity":"common","id":"gaxton","subtitle":"Hero","details":"Wilden's old college friend, a cheerful elf whose stories give Ian a glimpse of the father he never met.","image":"https://vignette.wikia.nocookie.net/disney/images/6/67/Gaxton_onward.png/revision/latest"},{"name":"Fenwick","rarity":"common","id":"fenwick","subtitle":"Monster","details":"A construction-worker cyclops on the highway crew, whose roadwork delays the Lightfoot brothers' quest westward.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/86/Onwardconstructioncyclops.png/revision/latest"},{"name":"Blazey","rarity":"common","id":"blazey","subtitle":"Animal","details":"The Lightfoots' pet dragon, a small fire-breathing house pet with the manners of an excitable puppy.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/07/Blazeyrender.jpg/revision/latest"},{"name":"Avel","rarity":"common","id":"avel","subtitle":"Hero","details":"A nervous elf officer on Colt Bronco's police force, reporting unicorn infestations and quest-related chaos alike.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2c/Avel.jpg/revision/latest"},{"name":"Grecklin","rarity":"common","id":"grecklin","subtitle":"Sidekick","details":"A goblin pawnshop owner in New Mushroomton, keeper of curiosities the Lightfoot brothers browse on their quest.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/58/Grecklin.jpg/revision/latest"},{"name":"Joe Gardner","rarity":"legendary","id":"joe-gardner","subtitle":"Hero","details":"A middle-school band teacher chasing his big jazz break, whose fall into a manhole lands his soul in the Great Before.","image":"https://vignette.wikia.nocookie.net/disney/images/3/31/Profile_-_Joe_Gardner.png/revision/latest"},{"name":"22","rarity":"legendary","id":"22","subtitle":"Spirit","details":"A cynical unborn soul who has dodged Earth for millennia, mentored by Lincoln and Mother Teresa, until Joe comes along.","image":"https://vignette.wikia.nocookie.net/disney/images/2/25/Profile_-_22.png/revision/latest"},{"name":"Terry","rarity":"rare","id":"terry","subtitle":"Spirit","details":"The Great Beyond's meticulous soul accountant, who notices one missing soul and hunts it through the streets of New York.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/01/Te.jpg/revision/latest"},{"name":"Jerry","rarity":"uncommon","id":"jerry","subtitle":"Spirit","details":"A serene counselor of the Great Before, one of the beings shaping new souls with the patience of the whole universe.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2e/Profile_-_Mayor_Jerry_Generazzo.png/revision/latest"},{"name":"Moonwind","rarity":"rare","id":"moonwind","subtitle":"Spirit","details":"A sign-spinning mystic whose soul sails the Astral Plane rescuing lost souls while his body dances on a corner.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bb/Moonwind.png/revision/latest"},{"name":"Dorothea Williams","rarity":"uncommon","id":"dorothea-williams","subtitle":"Heroine","details":"A legendary jazz saxophonist whose quartet spot Joe has chased his whole life, unimpressed by almost everyone.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/10/Dorotheasax.png/revision/latest"},{"name":"Mr. Mittens","rarity":"uncommon","id":"mr-mittens","subtitle":"Animal","details":"A therapy cat whose body Joe's soul accidentally occupies, to the horror of a cat-souled Joe watching from inside.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c0/Profile_-_Mr._Mittens.png/revision/latest"},{"name":"Libba Gardner","rarity":"uncommon","id":"libba-gardner","subtitle":"Heroine","details":"Joe's mother, a seamstress whose tailor shop truths about dreams and security her son finally hears in Soul.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6f/Libba_Gardner.jpg/revision/latest"},{"name":"Curley","rarity":"common","id":"curley","subtitle":"Hero","details":"Joe's former student turned drummer in Dorothea's band, the connection that finally opens the audition door for him.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/48/Souldrummer.png/revision/latest"},{"name":"Dez","rarity":"common","id":"dez","subtitle":"Hero","details":"Joe's barber, who hears more life stories in his chair than anyone and nearly gave his own years to the Navy instead.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/ad/Dez_Soul1.jpg/revision/latest"},{"name":"Connie","rarity":"common","id":"connie","subtitle":"Heroine","details":"Joe's trombone student, a young musician ready to quit band until her own playing reminds him why teaching matters.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/58/Conniesoultrombone.png/revision/latest"},{"name":"Paul","rarity":"common","id":"paul","subtitle":"Villain","details":"A blunt patron of Dez's barbershop, whose running commentary gives Joe's borrowed-cat day its loudest skeptic.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/51/Soul_2020_paul.jpg/revision/latest"},{"name":"Melba","rarity":"common","id":"melba","subtitle":"Human","details":"A fellow teacher at Joe's school, part of the ordinary staff-room world his jazz dreams keep pulling him away from.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6e/Melba_and_Lulu.webp/revision/latest"},{"name":"Luca Paguro","rarity":"legendary","id":"luca-paguro","subtitle":"Monster","details":"A young sea monster who discovers he turns human on dry land, and risks everything for a summer, a scooter, and school.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9e/Luca_Paguro_.png/revision/latest"},{"name":"Alberto Scorfano","rarity":"epic","id":"alberto-scorfano","subtitle":"Monster","details":"A confident sea-monster teen living alone in a tower, who teaches Luca to silence his Bruno and chase the surface.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5c/Human_Alberto.png/revision/latest"},{"name":"Giulia Marcovaldo","rarity":"epic","id":"giulia-marcovaldo","subtitle":"Heroine","details":"An energetic Portorosso girl who races the triathlon each summer and takes two strange new boys onto her team.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5c/Giulia_Marcovaldo.png/revision/latest"},{"name":"Ercole Visconti","rarity":"rare","id":"ercole-visconti","subtitle":"Villain","details":"Portorosso's preening triathlon champion, a Vespa-owning bully who cannot stand losing his cup to underdog newcomers.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/36/Image-8.png/revision/latest"},{"name":"Massimo Marcovaldo","rarity":"rare","id":"massimo-marcovaldo","subtitle":"Hero","details":"Giulia's father, a burly one-armed fisherman whose harpoon talk terrifies sea monsters until they taste his cooking.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f8/Image-9.png/revision/latest"},{"name":"Machiavelli","rarity":"uncommon","id":"machiavelli","subtitle":"Animal","details":"The Marcovaldos' deadpan cat, the first in Portorosso to smell that the new boys are not what they seem.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f9/Machiavelli.png/revision/latest"},{"name":"Daniela Paguro","rarity":"uncommon","id":"daniela-paguro","subtitle":"Monster","details":"Luca's mother, a sea monster who would keep her son safe in the deep even if it means sending him to the ocean floor.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/bc/Daniela.jpg/revision/latest"},{"name":"Lorenzo Paguro","rarity":"uncommon","id":"lorenzo-paguro","subtitle":"Monster","details":"Luca's father, a mild sea monster who raises prize crabs and worries quietly while Daniela runs the family defense.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4e/Lorenzo.jpg/revision/latest"},{"name":"Grandma Paguro","rarity":"uncommon","id":"grandma-paguro","subtitle":"Monster","details":"Luca's grandmother, who has been to the surface town herself and winks at rules the younger monsters treat as law.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/52/Daniela%27s_mother_%282%29.jpg.webp/revision/latest"},{"name":"Ciccio","rarity":"common","id":"ciccio","subtitle":"Sidekick","details":"One of Ercole's two triathlon teammates, a quiet enforcer in the Portorosso Cup champion's small entourage.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7b/Ciccio.png/revision/latest"},{"name":"Guido (Luca)","rarity":"common","id":"guido-luca","subtitle":"Sidekick","details":"Ercole's other teammate in Portorosso, a silent sidekick whose loyalty lasts exactly as long as Ercole's winning streak.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/78/GuidoLucaProfile.png/revision/latest"},{"name":"Mrs. Marsigliese","rarity":"common","id":"mrs-marsigliese","subtitle":"Human","details":"A Portorosso signora who sponsors the town's beloved race and keeps its summer traditions in strict order.","image":"https://vignette.wikia.nocookie.net/disney/images/1/15/Profile_-_Mrs._Marsigliese.jpg/revision/latest"},{"name":"Mei Lee","rarity":"legendary","id":"mei-lee","subtitle":"Heroine","details":"A thirteen-year-old Toronto girl who turns into a giant red panda whenever her emotions run high, which is often.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/53/Mei_Lee.png/revision/latest"},{"name":"Miriam Mendelsohn","rarity":"rare","id":"miriam-mendelsohn","subtitle":"Sidekick","details":"Mei's loyal, cap-wearing best friend, the steady heart of their four-girl crew through every panda emergency.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/45/Miriam-_Turning_Red.jpg/revision/latest"},{"name":"Priya Mangal","rarity":"uncommon","id":"priya-mangal","subtitle":"Sidekick","details":"Mei's deadpan best friend, whose monotone delivery and vampire novels hide perfect comic timing and total loyalty.","image":"https://vignette.wikia.nocookie.net/disney/images/5/58/Priya_%28Turning_Red%29.jpg/revision/latest"},{"name":"Abby Park","rarity":"rare","id":"abby-park","subtitle":"Sidekick","details":"Mei's fiercely intense best friend, a tiny powerhouse ready to fight the whole school on behalf of her crew.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b5/Screenshot_2022-03-18_8.02.04_PM.png/revision/latest"},{"name":"Ming Lee","rarity":"rare","id":"ming-lee","subtitle":"Heroine","details":"Mei's overprotective mother, keeper of the family temple, whose own panda is far bigger than anyone suspects.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e5/Ming_Lee.png/revision/latest"},{"name":"Tyler Nguyen-Baker","rarity":"uncommon","id":"tyler-nguyen-baker","subtitle":"Villain","details":"The class bully who torments Mei until his secret boy-band fandom makes him the crew's most unlikely customer.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5b/Tylerimage.png/revision/latest"},{"name":"Robaire","rarity":"common","id":"robaire","subtitle":"Hero","details":"The lead singer of 4*TOWN, Mei's beloved boy band, whose concert becomes the crew's fundraising finish line.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1f/Robaire.png/revision/latest"},{"name":"Jin Lee","rarity":"common","id":"jin-lee","subtitle":"Hero","details":"Mei's quiet father, whose cooking steadies the family and whose calm words help his daughter face the ritual.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7f/Jin_Lee.png/revision/latest"},{"name":"Grandma Wu","rarity":"uncommon","id":"grandma-wu","subtitle":"Heroine","details":"Mei's formidable grandmother, who arrives from Florida with the aunties to contain the panda, as she once did for Ming.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7c/%28Turning_Red%29_Grandma_Wu.png/revision/latest"},{"name":"Mr. Gao","rarity":"common","id":"mr-gao","subtitle":"Sidekick","details":"The Lees' elderly neighbor and a shaman who knows the red panda ritual, guiding Mei's family through the red moon.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/50/Mr._Gao.jpg/revision/latest"},{"name":"Devon","rarity":"common","id":"devon","subtitle":"Human","details":"The convenience-store clerk Mei crushes on, whose imagined romance fuels a sketchbook that horrifies her mother.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/76/Devon.jpg/revision/latest"},{"name":"Jesse","rarity":"common","id":"jesse","subtitle":"Hero","details":"A member of 4*TOWN, one of the five voices Mei and her friends scheme to see live at the Toronto concert.","image":"https://vignette.wikia.nocookie.net/disney/images/4/44/Turning_Red_-_Jesse_Render.jpg/revision/latest"},{"name":"Tae Young","rarity":"common","id":"tae-young","subtitle":"Hero","details":"The soft-spoken member of 4*TOWN beloved for his love of animals, a favorite of Mei's whole friend group.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c1/Turning_Red_-_Tae_Young_Render.jpg/revision/latest"},{"name":"Aaron T.","rarity":"common","id":"aaron-t","subtitle":"Hero","details":"A member of 4*TOWN, part of the five-boy lineup whose concert tickets drive the girls' merch empire.","image":"https://vignette.wikia.nocookie.net/disney/images/d/df/Turning_Red_-_Aaron_T_Render.jpg/revision/latest"},{"name":"Aaron Z.","rarity":"common","id":"aaron-z","subtitle":"Hero","details":"The other Aaron of 4*TOWN, rounding out the boy band whose show collides with Mei's panda ritual night.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7f/Turning_Red_-_Aaron_Z_Render.jpg/revision/latest"},{"name":"Stacy Frick","rarity":"common","id":"stacy-frick","subtitle":"Human","details":"A classmate of Mei's, the first to spot the panda in the school bathroom and spread the legend of the red panda sighting.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ee/Stacy_frick.png/revision/latest"},{"name":"Carter Murphy-Mayhew","rarity":"common","id":"carter-murphy-mayhew","subtitle":"Human","details":"A goth-leaning classmate who becomes an unlikely red panda admirer, cheering Mei's fluffiest form at school.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/84/Carter_Murphy_Mayhew.jpg/revision/latest"},{"name":"Ember Lumen","rarity":"legendary","id":"ember-lumen","subtitle":"Heroine","details":"A fire element with a quick temper who runs her father's Element City shop and dreams past the life she inherited.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/36/Profile_-_Ember_Lumen.png/revision/latest"},{"name":"Wade Ripple","rarity":"legendary","id":"wade-ripple","subtitle":"Hero","details":"A water element city inspector whose leak in the shop's pipes, and easy tears, flood Ember's carefully planned future.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0f/Profile_-_Wade_Ripple.png/revision/latest"},{"name":"Gale Cumulus","rarity":"uncommon","id":"gale-cumulus","subtitle":"Spirit","details":"An air element executive and Gale-ball superfan, Wade's boss at City Hall, who holds the shop's fate in her hands.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/02/Profile_-_Gale.jpg/revision/latest"},{"name":"Bernie Lumen","rarity":"rare","id":"bernie-lumen","subtitle":"Spirit","details":"Ember's father, a fire immigrant who built the Fireplace shop from nothing and waits for his daughter to take over.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/da/Bernie_Lumen_Pose.png/revision/latest"},{"name":"Cinder Lumen","rarity":"uncommon","id":"cinder-lumen","subtitle":"Spirit","details":"Ember's mother, a matchmaker with a gift for smelling love, who tests every suitor who drifts toward her daughter.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8c/Cinder_Lumen.png/revision/latest"},{"name":"Brook Ripple","rarity":"uncommon","id":"brook-ripple","subtitle":"Spirit","details":"Wade's mother, an architect in a watery high-rise who welcomes Ember with more warmth than her son expected.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2d/5022_BrookeRipple_34_38320.png/revision/latest"},{"name":"Clod","rarity":"uncommon","id":"clod","subtitle":"Spirit","details":"A young earth element with a crush on Ember, who blooms a flower every time he tries to impress her at the shop.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/98/5024_Clod_34_86175.png/revision/latest"},{"name":"Alan Ripple","rarity":"common","id":"alan-ripple","subtitle":"Spirit","details":"Wade's brother, part of the sprawling Ripple family filling their Element City home with cheerful water chaos.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d0/5023_AlanRipple_40_53991.png/revision/latest"},{"name":"Fern Grouchwood","rarity":"common","id":"fern-grouchwood","subtitle":"Spirit","details":"A slow-moving fern-like bureaucrat at City Hall, whose red tape Wade must survive to save Ember's family shop.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a6/5025_Fern_40_32831.png/revision/latest"},{"name":"Lake Ripple","rarity":"common","id":"lake-ripple","subtitle":"Spirit","details":"A young Ripple family member at the Element City gathering, part of Wade's warm and watery extended clan.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/88/Lake_Ripple_Pose.png/revision/latest"},{"name":"Marco","rarity":"common","id":"marco","subtitle":"Spirit","details":"One of the Ripple family's younger generation in Elemental, splashing through the background of Wade's home life.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/bf/Marco_and_Polo_Ripple_Pose.png/revision/latest"},{"name":"Polo","rarity":"common","id":"polo","subtitle":"Spirit","details":"Marco's counterpart among the young Ripples, another small water element in the family's crowded household scenes.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/bf/Marco_and_Polo_Ripple_Pose.png/revision/latest"},{"name":"Harold","rarity":"common","id":"harold","subtitle":"Spirit","details":"An earthy Element City resident in the shop's orbit, part of the neighborhood mix Ember's family serves each day.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/42/Harold_Ripple_Pose.png/revision/latest"},{"name":"Flarrietta","rarity":"common","id":"flarrietta","subtitle":"Spirit","details":"A fire element regular around the Lumen family shop, one of Firetown's colorful neighbors in Elemental.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/76/Flarrietta.png/revision/latest"},{"name":"Gibly","rarity":"common","id":"gibly","subtitle":"Spirit","details":"Another of Firetown's residents in Elemental, a background neighbor in the close-knit fire community Ember serves.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6a/Ghibli_Pose.png/revision/latest"},{"name":"Eddie","rarity":"common","id":"eddie","subtitle":"Spirit","details":"An Element City local in the Lumens' neighborhood circle, part of the everyday crowd around the Fireplace shop.","image":"https://vignette.wikia.nocookie.net/worldofcarsdrivein/images/3/3c/Eddie.webp/revision/latest"},{"name":"Elio Solis","rarity":"legendary","id":"elio-solis","subtitle":"Hero","details":"An eleven-year-old space fanatic who accidentally becomes Earth's ambassador to the Communiverse in Elio.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e8/Profile_-_Elio_Solis.jpg/revision/latest"},{"name":"Glordon","rarity":"epic","id":"glordon","subtitle":"Alien","details":"A young alien prince and Elio's first friend among the stars, whose armored father wants him bred for war instead.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9a/Profile_-_Glordon.jpg/revision/latest"},{"name":"Lord Grigon","rarity":"rare","id":"lord-grigon","subtitle":"Villain","details":"Glordon's father, a hulking warlord angling for a Communiverse seat, whose rejection turns him toward Earth.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/33/Profile_-_Lord_Grigon.jpg/revision/latest"},{"name":"Olga Solis","rarity":"rare","id":"olga-solis","subtitle":"Heroine","details":"Elio's aunt, an Air Force major raising him after his parents' death, whose coded messages reach him across space.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7e/Profile_-_Olga_Solis.png/revision/latest"},{"name":"OOOOO","rarity":"uncommon","id":"ooooo","subtitle":"Robot","details":"A cheerful, shape-shifting supercomputer of the Communiverse, the liquid-metal guide who translates the galaxy for Elio.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/90/Profile_-_Ooooo.png/revision/latest"},{"name":"Ambassador Questa","rarity":"uncommon","id":"ambassador-questa","subtitle":"Alien","details":"A graceful Communiverse ambassador, one of the council beings who mistake young Elio for Earth's true leader.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/af/Profile_-_Ambassador_Questa.jpg/revision/latest"},{"name":"Ambassador Helix","rarity":"uncommon","id":"ambassador-helix","subtitle":"Alien","details":"A spiral-shelled ambassador of the Communiverse council, part of the alien assembly judging Earth's membership.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d3/Profile_-_Ambassador_Helix.png/revision/latest"},{"name":"Ambassador Tegmen","rarity":"common","id":"ambassador-tegmen","subtitle":"Alien","details":"Another of the Communiverse's ambassadors, a council voice in the grand chamber where Elio must speak for Earth.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a6/Profile_-_Amassador_Tegmen.png/revision/latest"},{"name":"Ambassador Mira","rarity":"common","id":"ambassador-mira","subtitle":"Alien","details":"A Communiverse ambassador among the council who welcome the supposed leader of Earth into their star chamber.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7c/Profile_-_Ambassador_Mira.png/revision/latest"},{"name":"Ambassador Naos","rarity":"common","id":"ambassador-naos","subtitle":"Alien","details":"One of the alien ambassadors of the Communiverse, witnessing Earth's case through the words of an eleven-year-old.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fc/Profile_-_Ambassador_Naos.png/revision/latest"},{"name":"Gunther Melmac","rarity":"common","id":"gunther-melmac","subtitle":"Sidekick","details":"A conspiracy-minded military staffer tracking alien signals, whose theories about visitors sound crazier than the truth.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fb/Profle_-_Gunther_Melmac.jpg/revision/latest"},{"name":"Bryce","rarity":"common","id":"bryce","subtitle":"Villain","details":"A camp bully in Elio whose teasing of the space-obsessed boy turns into something crueler before the launch.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/85/Profle_-_Bryce.jpg/revision/latest"},{"name":"Caleb","rarity":"common","id":"caleb","subtitle":"Villain","details":"Another of the camp boys who torment Elio, part of the earthly cruelty that makes the stars look kinder by comparison.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/41/Profile_-_Caleb.png/revision/latest"},{"name":"Luxo Jr.","rarity":"rare","id":"luxo-jr","subtitle":"Lamp","details":"Pixar's hopping desk-lamp mascot, a small lamp whose playful bouncing with a rubber ball became the studio's emblem.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7d/Luxo-cropped-only_for_mainpage.jpg/revision/latest"},{"name":"Dumpling","rarity":"uncommon","id":"dumpling","subtitle":"Sidekick","details":"The steamed bun a lonely mother raises like a baby in Bao, growing up bite by bite until she cannot let him go.","image":"https://vignette.wikia.nocookie.net/disney/images/c/ca/Bao_3.jpg/revision/latest"},{"name":"Piper","rarity":"rare","id":"piper","subtitle":"Animal","details":"A baby sandpiper in the short Piper, who overcomes her fear of the waves and learns to hunt by watching the crabs.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/bb/Piper-looking.jpg/revision/latest"},{"name":"Tinny","rarity":"common","id":"tinny","subtitle":"Toy","details":"A one-man-band tin toy in Tin Toy, terrified of a drooling baby and brave enough to march back into the chaos anyway.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/ce/Tinny.png/revision/latest"},{"name":"Knick","rarity":"uncommon","id":"knick","subtitle":"Toy","details":"A snow-globe snowman in Knick Knack, scheming for years to escape his dome and join the other souvenirs in the sun.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c7/Snowman.png/revision/latest"},{"name":"Winston","rarity":"uncommon","id":"winston","subtitle":"Animal","details":"A hungry Boston terrier in Feast, whose love story with his owner is told entirely through the meals at his bowl.","image":"https://vignette.wikia.nocookie.net/disney/images/4/46/Feast_Winston%27s_first_meal.JPG/revision/latest"},{"name":"Uku","rarity":"common","id":"uku","subtitle":"Spirit","details":"A small ukulele-voiced volcano in Lava, who sings across the ages for a volcano of his own to love.","image":"https://vignette.wikia.nocookie.net/disney/images/3/31/Lava_Character.jpg/revision/latest"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
